import React from "react";

interface StatCardProps {
  label: string;
  value: string;
  change: string;
  trend: "up" | "down" | "neutral";
  valueColor?: "default" | "green" | "red" | "blue";
}

const valueColorMap = {
  default: "text-gray-900",
  green: "text-emerald-600",
  red: "text-red-500",
  blue: "text-blue-500",
};

const StatCard: React.FC<StatCardProps> = ({
  label,
  value,
  change,
  trend,
  valueColor = "default",
}) => (
  <div className="bg-white border border-gray-100 rounded-xl p-4 flex flex-col gap-1">
    <span className="text-xs text-gray-500">{label}</span>
    <span className={`text-2xl font-medium ${valueColorMap[valueColor]}`}>{value}</span>
    <span
      className={`text-xs ${
        trend === "up" ? "text-emerald-600" : trend === "down" ? "text-red-500" : "text-gray-400"
      }`}
    >
      {trend === "up" ? "↑" : trend === "down" ? "↓" : "–"} {change}
    </span>
  </div>
);

export default StatCard;
